class FavoritesManager{constructor(){this.favorites=this.loadFavorites(),this.init()}init(){this.updateFavoritesCount(),this.setupEventListeners()}setupEventListeners(){document.getElementById("favorites-toggle").addEventListener("click",()=>{this.toggleFavoriteView();var e=document.getElementById("modal-home");e&&e.addEventListener("click",()=>this.goHome())})}loadFavorites(){var e=localStorage.getItem("pokedex-favorites");return e?JSON.parse(e):[]}saveFavorites(){localStorage.setItem("pokedex-favorites",JSON.stringify(this.favorites)),this.updateFavoritesCount()}isFavorite(t){return this.favorites.some(e=>e.id===t)}toggleFavorite(t){var e=this.favorites.findIndex(e=>e.id===t.id);-1===e?this.favorites.push({id:t.id,name:t.name,sprite:t.sprites.front_default,types:t.types}):this.favorites.splice(e,1),this.saveFavorites()}toggleFavoriteView(){document.body.classList.contains("showing-favorites")?this.showAllPokemons():this.showFavorites()}showFavorites(){if(0===this.favorites.length)this.showNoFavoritesMessage();else{document.body.classList.add("showing-favorites");let s=document.getElementById("pokemon-grid");s.innerHTML="",this.favorites.forEach(async e=>{try{var t=await window.pokeAPI.fetchPokemon(e.id),o=window.pokemonManager.createPokemonCard(t);s.appendChild(o)}catch(e){console.error("Erro ao carregar favorito:",e)}}),document.getElementById("pagination").style.display="none",document.getElementById("favorites-toggle").textContent="🏠 Voltar"}}showAllPokemons(){document.body.classList.remove("showing-favorites"),window.pokemonManager.renderPokemonGrid(),document.getElementById("pagination").style.display="flex",this.updateFavoritesButton()}showNoFavoritesMessage(){document.getElementById("pokemon-grid").innerHTML=`
            <div class="no-favorites">
                <h3>💫 Nenhum favorito ainda</h3>
                <p>Clique na estrela dos Pokémons para adicioná-los aos seus favoritos!</p>
                <button onclick="window.favoritesManager.showAllPokemons()" class="btn">
                    Explorar Pokémons
                </button>
            </div>
        `,document.body.classList.add("showing-favorites"),document.getElementById("pagination").style.display="none",document.getElementById("favorites-toggle").textContent="🏠 Voltar"}updateFavoritesCount(){document.getElementById("favorites-count").textContent=this.favorites.length}updateFavoritesButton(){document.getElementById("favorites-toggle").innerHTML=`⭐ Favoritos (<span id="favorites-count">${this.favorites.length}</span>)`}}